int maxProfit(int* prices, int pricesSize) {
    if (pricesSize <= 1) return 0;
    int sold = 0, held = -1000000000, reset = 0;
    for (int i = 0; i < pricesSize; i++) {
        int pre_sold = sold;
        sold = held + prices[i];
        if (reset - prices[i] > held) held = reset - prices[i];
        if (pre_sold > reset) reset = pre_sold;
    }
    return sold > reset ? sold : reset;
}

