class Solution {
public:
    int maxProfit(vector<int>& prices) {
        if (prices.empty()) return 0;
        int sold = 0, held = -1e9, reset = 0;
        for (int p : prices) {
            int pre_sold = sold;
            sold = held + p;
            held = max(held, reset - p);
            reset = max(reset, pre_sold);
        }
        return max(sold, reset);
    }
};

